function financeCategories(){state.settings.personalFinanceCategories ||= [];let changed=false;state.settings.personalFinanceCategories=state.settings.personalFinanceCategories.map((x,i)=>{if(x&&typeof x==='object'){const y={...x,id:String(x.id||('cat-'+i+'-'+String(x.name||'').toLowerCase().replace(/[^a-zа-я0-9]+/gi,'-'))),name:String(x.name||'Без названия'),kind:['income','expense','both'].includes(String(x.kind))?String(x.kind):'both'};if(!x.id||!x.name||!x.kind)changed=true;return y}changed=true;return {id:'cat-legacy-'+i,name:String(x||'Без названия'),kind:'both'}});if(changed){saveLocalOnly();queueFinanceCacheWrite()}return state.settings.personalFinanceCategories}
function financeCategoryName(categoryId,fallback=''){const c=financeCategories().find(x=>String(x.id)===String(categoryId));return c?.name||fallback||'Без категории'}
function financeCategoryIncludedInTotal(categoryId,categoryName=''){const id=String(categoryId||''),name=String(categoryName||'').trim().toLowerCase(),category=financeCategories().find(x=>(id&&String(x.id)===id)||(!id&&name&&String(x.name||'').trim().toLowerCase()===name));return category?category.includeInTotal!==false:true}
async function financeSetCategoryIncludedInTotal(categoryId,enabled){const category=financeCategories().find(x=>String(x.id)===String(categoryId));if(!category)return alert('Категория не найдена');try{await financeRunLocalMutation(()=>{category.includeInTotal=Boolean(enabled);category.updatedAt=Date.now();return category},()=>[financeCommand('/api/finance/categories/'+encodeURIComponent(categoryId),{method:'PUT',body:{category:{includeInTotal:Boolean(enabled)}}})])}catch(e){alert('Не удалось сохранить настройку категории локально: '+String(e.message||e))}}
function financeAccountName(accountId,fallback=''){const a=financeAccounts().find(x=>String(x.id)===String(accountId));return a?.name||fallback||'Счёт'}

async function financeSetAccountIncludedInTotal(accountId,enabled){const account=financeAccounts().find(x=>String(x.id)===String(accountId));if(!account)return alert('Счёт не найден');try{await financeRunLocalMutation(()=>{account.ignoreInBalance=!Boolean(enabled);financeLocalTouchAccount(account);return account},()=>[financeCommand('/api/finance/accounts/'+encodeURIComponent(accountId),{method:'PUT',body:{account:{ignoreInBalance:!Boolean(enabled)}}})])}catch(e){alert('Не удалось сохранить настройку счёта локально: '+String(e.message||e))}}
function financeTransactionType(x){if(x?.type)return String(x.type);if(x?.kind==='adjustment')return'adjustment';return Number(x?.amount)<0?'expense':'income'}
function financeTransactionAmount(x){return Math.abs(Number(x?.amount)||0)}
function financeTransactionDefaultAmount(x){const n=Number(x?.defaultAmount);return Number.isFinite(n)?Math.abs(n):financeTransactionAmount(x)}
function financeTransactionTime(x){const raw=Number(x?.createdAt||x?.dateTs||0);if(raw)return raw;const s=String(x?.date||'');const m=s.match(/^(\d{2})\.(\d{2})\.(\d{4})$/);if(m)return new Date(Number(m[3]),Number(m[2])-1,Number(m[1])).getTime();const parsed=Date.parse(s);return Number.isFinite(parsed)?parsed:0}
function financeNowDate(){return new Date().toLocaleDateString('ru-RU')}
function financeCurrencySymbol(code='KZT'){return ({KZT:'₸',USD:'$',CNY:'¥',EUR:'€',RUB:'₽'})[String(code).toUpperCase()]||String(code).toUpperCase()}
function financeMoney(value,currency='KZT'){const n=Number(value)||0,code=String(currency||'KZT').toUpperCase();if(code==='KZT')return fmt(n);return new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(n)+' '+financeCurrencySymbol(code)}
function financeAccountDefaultBalance(a){const currency=String(a?.currency||'KZT').toUpperCase();if(currency==='KZT')return Number(a?.balance)||0;if(Number.isFinite(Number(a?.balanceDefault)))return Number(a.balanceDefault);return 0}
function financeVisibleAccounts(){return financeAccounts().filter(x=>!x.removed&&!x.archived)}
function financeVisibleCategories(){return financeCategories().filter(x=>!x.archived)}
function financeAddAccount(){openModal('financeAccount')}
function financeEditAccount(accountId){if(financeAccounts().some(x=>String(x.id)===String(accountId)))openModal('financeAccount',accountId)}
function financeAdjustAccount(accountId){if(financeAccounts().some(x=>String(x.id)===String(accountId)))openModal('financeAdjustment',accountId)}
function updateFinanceAdjustmentPreview(){const accountId=String(document.getElementById('financeAdjustmentAccountId')?.value||''),account=financeAccounts().find(x=>String(x.id)===accountId),next=Number(document.getElementById('financeAdjustmentAmount')?.value),preview=document.getElementById('financeAdjustmentPreview');if(!preview||!account)return;preview.textContent=Number.isFinite(next)?'Новый баланс: '+financeMoney(next,account.currency||'KZT'):'Введите новый баланс счёта'}


function financeUpsertLocal(list,row){if(!row?.id)return;const next={...row};if(Number.isFinite(Number(next.updatedAt)))next._syncUpdatedAt=Number(next.updatedAt);const i=list.findIndex(x=>String(x.id)===String(next.id));if(i>=0)list[i]=next;else list.push(next)}

function financeStatementIdentity(x){const key=String(x?.bankOperationKey||'').trim(),fp=String(x?.statementFingerprint||'').trim(),scope=String(x?.statementAccountId||x?.accountId||'').trim(),identity=key?'bank:'+key:(fp?'fp:'+fp:'');return identity?(scope?scope+'|':'')+identity:''}
function financeRevealStatementRows(accountId='',rows=[]){const times=(Array.isArray(rows)?rows:[]).map(financeTransactionTime).filter(x=>Number.isFinite(x)&&x>0);if(times.length){const from=new Date(Math.min(...times)),to=new Date(Math.max(...times));from.setHours(0,0,0,0);to.setHours(0,0,0,0);to.setDate(to.getDate()+1);financeHistoryPeriodOverride={start:from.getTime(),end:to.getTime(),label:'Период выписки'}}const type=document.getElementById('financeTypeFilter'),account=document.getElementById('financeAccountFilter'),category=document.getElementById('financeCategoryFilter'),panel=document.getElementById('financeOperationsPanel');if(type)type.value='all';if(account){const id=String(accountId||'');account.value=[...account.options].some(x=>x.value===id)?id:'all'}if(category)category.value='all';if(panel)panel.open=true;renderFinanceTransactions();setTimeout(()=>panel?.scrollIntoView({behavior:'smooth',block:'start'}),50)}
function financeMergeServerArray(localRows,remoteRows,{statements=false,preferRemote=false}={}){const out=[],byId=new Map(),byStatement=new Map(),version=x=>Math.max(Number(x?._syncUpdatedAt)||0,Number(x?.updatedAt)||0),prefer=(a,b)=>{const ap=String(a?.bankStatus||'')==='posted',bp=String(b?.bankStatus||'')==='posted';if(ap!==bp)return bp?b:a;return version(b)>=version(a)?b:a};for(const raw of Array.isArray(localRows)?localRows:[]){const row={...raw},id=String(row?.id||'');if(!id)continue;const identity=statements?financeStatementIdentity(row):'';if(identity&&byStatement.has(identity)){const i=byStatement.get(identity),chosen=prefer(out[i],row),oldId=String(out[i]?.id||'');out[i]=chosen;if(oldId&&oldId!==String(chosen.id||''))byId.delete(oldId);byId.set(String(chosen.id||''),i);continue}const i=out.push(row)-1;byId.set(id,i);if(identity)byStatement.set(identity,i)}for(const remote of Array.isArray(remoteRows)?remoteRows:[]){if(!remote?.id)continue;const id=String(remote.id),identity=statements?financeStatementIdentity(remote):'',sameStatement=identity?byStatement.get(identity):undefined;let i=byId.get(id);if(i===undefined&&sameStatement!==undefined)i=sameStatement;if(i===undefined){out.push({...remote});const n=out.length-1;byId.set(id,n);if(identity)byStatement.set(identity,n);continue}const local=out[i],lv=version(local),rv=version(remote);if(preferRemote||rv>=lv||String(local?.id||'')!==id){const oldId=String(local?.id||'');out[i]={...local,...remote};if(oldId&&oldId!==id)byId.delete(oldId);byId.set(id,i);if(identity)byStatement.set(identity,i)}}return out}
function financeMergeServerSnapshot(local,remote,{preferRemote=false}={}){local=normalizeFinanceSnapshot(local);remote=normalizeFinanceSnapshot(remote);return {accounts:financeMergeServerArray(local.accounts,remote.accounts,{preferRemote}),categories:financeMergeServerArray(local.categories,remote.categories,{preferRemote}),transactions:financeMergeServerArray(local.transactions,remote.transactions,{statements:true,preferRemote}),imports:{...(remote.imports||{}),...(local.imports||{})}}}
async function financeApplyServerAck(data,cmd=null){if(!data||typeof data!=='object')return false;let changed=false;const upsertMany=(list,rows)=>{for(const row of Array.isArray(rows)?rows:[]){if(!row?.id)continue;financeUpsertLocal(list,row);changed=true}},upsertTransactions=rows=>{const list=financeTransactions();for(const row of Array.isArray(rows)?rows:[]){if(!row?.id)continue;const identity=financeStatementIdentity(row);if(identity){for(let i=list.length-1;i>=0;i--)if(String(list[i]?.id||'')!==String(row.id)&&financeStatementIdentity(list[i])===identity){list.splice(i,1);changed=true}}financeUpsertLocal(list,row);changed=true}},path=String(cmd?.path||'');if(data.account?.id){financeUpsertLocal(financeAccounts(),data.account);changed=true}upsertMany(financeAccounts(),data.accounts);if(data.category?.id){financeUpsertLocal(financeCategories(),data.category);changed=true}upsertMany(financeCategories(),data.categories);if(data.transaction?.id)upsertTransactions([data.transaction]);upsertTransactions(data.transactions);upsertTransactions(data.skippedTransactions);if(data.deletedId){const id=String(data.deletedId),list=path.includes('/transactions/')?financeTransactions():path.includes('/categories/')?financeCategories():path.includes('/accounts/')?financeAccounts():null;if(list){const i=list.findIndex(x=>String(x.id)===id);if(i>=0){list.splice(i,1);changed=true}}}if(changed){await financeCacheWrite(financeStateSnapshot());try{renderFinance()}catch(e){console.error('finance render after server ack failed',e)}}return changed}
async function financeReconcileFromServer({force=false}={}){if(financeReconcileInFlight||!navigator.onLine||!financeStorageHealthy)return false;financeReconcileInFlight=true;try{const pending=await financeOutboxRead();if(!financeStorageHealthy||pending.length)return false;if(!force){const meta=await fetchFinanceCloud(true),revision=Number(meta.revision||0);financeRemoteUpdatedAt=Math.max(financeRemoteUpdatedAt,Number(meta.updatedAt||0));if(revision<=financeRemoteRevision){financeRemoteReady=true;return true}}const data=await fetchFinanceCloud(false),remote=normalizeFinanceSnapshot(data),local=normalizeFinanceSnapshot(financeStateSnapshot()),merged=financeMergeServerSnapshot(local,remote,{preferRemote:true});financeRemoteRevision=Math.max(financeRemoteRevision,Number(data.revision||0));financeRemoteUpdatedAt=Math.max(financeRemoteUpdatedAt,Number(data.updatedAt||0));financeRemoteReady=true;if(JSON.stringify(merged)!==JSON.stringify(local)){applyFinanceSnapshot(merged);await financeCacheWrite(merged);try{renderFinance()}catch(e){console.error('finance render after reconcile failed',e)}}return true}catch(e){console.warn('finance reconcile failed',e);return false}finally{financeReconcileInFlight=false}}
async function financeLedgerRequest(path,{method='GET',body=null,headers=null}={}){const mutating=String(method||'GET').toUpperCase()!=='GET';if(mutating)financeSyncStatus('серверная операция…');try{const r=await fetch(MILLIONER_API+path,{method,headers:{Accept:'application/json',...(body==null?{}:{'Content-Type':'application/json'}),...(headers||{})},...(body==null?{}:{body:JSON.stringify(body)})});let data={};try{data=await r.json()}catch{}if(!r.ok||data.ok===false)throw new Error(data.error||data.message||('HTTP '+r.status));return data}catch(e){if(mutating)financeSyncStatus('локально сохранено · сервер недоступен','bad');throw e}}


async function financeReloadFromServer({explicit=false,clearOutbox=false}={}){if(!explicit)return false;const data=await fetchFinanceCloud(false),snap=normalizeFinanceSnapshot(data);if(clearOutbox)await financeOutboxClear();financeRemoteRevision=Number(data.revision||0);financeRemoteUpdatedAt=Number(data.updatedAt||0);financeRemoteReady=true;applyFinanceSnapshot(snap);await financeCacheWrite(snap);await financeUpdateLocalSyncStatus();renderFinance();return true}
async function saveFinanceAdjustment(accountId){const account=financeAccounts().find(x=>String(x.id)===String(accountId)),next=Number(document.getElementById('financeAdjustmentAmount')?.value);if(!account)return alert('Счёт не найден');if(!Number.isFinite(next))return alert('Укажите новый баланс');const current=Number(account.balance)||0,delta=next-current;if(Math.abs(delta)<.000001)return alert('Баланс уже равен указанной сумме');const now=Date.now(),tx={id:'fin-adj-'+now,type:'adjustment',kind:'adjustment',accountId,amount:delta,...(String(account.currency||'KZT')==='KZT'?{defaultAmount:Math.abs(delta)}:{}),currency:account.currency||'KZT',title:'Изменение баланса · '+account.name,note:'',date:financeNowDate(),createdAt:now,updatedAt:now,excludedFromAnalytics:true,affectsBalance:true,balanceBefore:current,balanceAfter:next};try{await financeRunLocalMutation(()=>financeLocalCreateTransaction(tx),()=>[financeCommand('/api/finance/accounts/'+encodeURIComponent(accountId)+'/adjust-balance',{method:'POST',body:{id:tx.id,balance:next,date:tx.date},acceptStatuses:[409]})]);closeModal()}catch(e){alert('Не удалось изменить баланс локально: '+String(e.message||e))}}
async function saveFinanceAccount(accountId=''){const name=String(document.getElementById('financeAccountName')?.value||'').trim(),iban=String(document.getElementById('financeAccountIban')?.value||'').toUpperCase().replace(/[^A-Z0-9]/g,''),cardNumber=String(document.getElementById('financeAccountCard')?.value||'').replace(/[^0-9*Xx]/g,'');if(!name)return alert('Введите название счёта');try{if(accountId){const account=financeAccounts().find(x=>String(x.id)===String(accountId));if(!account)return alert('Счёт не найден');await financeRunLocalMutation(()=>{account.name=name;if(iban){account.iban=iban;account.accountNumber=iban;account.bankAccountNumber=iban;account.bankStatementAccountNumber=iban}else{delete account.iban;delete account.accountNumber;delete account.bankAccountNumber;delete account.bankStatementAccountNumber}if(cardNumber){account.cardNumber=cardNumber;account.bankStatementCardNumber=cardNumber}else{delete account.cardNumber;delete account.bankStatementCardNumber};financeLocalTouchAccount(account);return account},()=>[financeCommand('/api/finance/accounts/'+encodeURIComponent(accountId),{method:'PUT',body:{account:{name,iban,accountNumber:iban,bankAccountNumber:iban,cardNumber}}})])}else{const balance=Number(document.getElementById('financeAccountBalance')?.value);if(!Number.isFinite(balance))return alert('Укажите текущий баланс');const now=Date.now(),account={id:'acc-'+now,name,balance,balanceDefault:balance,currency:'KZT',ignoreInBalance:false,...(iban?{iban,accountNumber:iban,bankAccountNumber:iban}:{}),...(cardNumber?{cardNumber}:{}),createdAt:now,updatedAt:now};await financeRunLocalMutation(()=>{financeAccounts().push(account);return account},()=>[financeCommand('/api/finance/accounts',{method:'POST',body:{account}})])}closeModal()}catch(e){alert('Не удалось сохранить счёт локально: '+String(e.message||e))}}
async function financeDeleteAccount(accountId){const account=financeAccounts().find(x=>String(x.id)===String(accountId));if(!account)return;const used=financeTransactions().filter(x=>String(x.accountId)===String(accountId)||String(x.toAccountId)===String(accountId)).length,balance=Number(account.balance)||0,message=used?'Удалить счёт «'+account.name+'» из списка?\n\nВсе '+used+' операций останутся в журнале и сохранят название счёта.'+(Math.abs(balance)>.000001?'\n\nТекущий остаток '+financeMoney(balance,account.currency||'KZT')+' перестанет входить в Итого.':''):'Удалить пустой счёт «'+account.name+'»?';if(!confirm(message))return;try{await financeRunLocalMutation(()=>{if(used){account.archived=true;account.ignoreInBalance=true;financeLocalTouchAccount(account)}else{const i=financeAccounts().findIndex(x=>String(x.id)===String(accountId));if(i>=0)financeAccounts().splice(i,1)}return {used}},()=>[financeCommand('/api/finance/accounts/'+encodeURIComponent(accountId),{method:'DELETE',acceptStatuses:[404]})]);if(used)alert('Счёт удалён из списка. '+used+' операций сохранены в журнале.')}catch(e){alert('Не удалось удалить счёт локально: '+String(e.message||e))}}
function financeMoveAccountOperations(accountId){const source=financeAccounts().find(x=>String(x.id)===String(accountId));if(!source)return;const used=financeTransactions().filter(x=>String(x.accountId)===String(accountId)||String(x.toAccountId)===String(accountId)).length,targets=financeVisibleAccounts().filter(x=>String(x.id)!==String(accountId)&&String(x.currency||'KZT')===String(source.currency||'KZT'));if(!used)return alert('На этом счёте нет операций для переноса.');if(!targets.length)return alert('Нет другого счёта в валюте '+String(source.currency||'KZT')+' для переноса.');showSheet('<h3>Перенести операции</h3><div class="link-note"><b>'+esc(source.name)+'</b> · операций: '+used+'<br>Баланс счёта не переносится и не складывается — меняется только привязка истории.</div><div class="field"><label>На какой счёт перенести</label><select id="financeMoveAccountTarget"><option value="">Выберите счёт</option>'+targets.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+'</option>').join('')+'</select></div><div class="actions"><button class="btn" onclick="closeModal()">Отмена</button><button class="btn dark" onclick="financeExecuteMoveAccountOperations(\''+esc(source.id)+'\',false)">Перенести</button></div><button class="btn full" style="margin-top:8px;color:#b42318" onclick="financeExecuteMoveAccountOperations(\''+esc(source.id)+'\',true)">Перенести и удалить исходный счёт</button><div class="link-note">Если между этими двумя счетами были переводы, после объединения они станут переводами внутри одного счёта и будут удалены как лишние.</div>')}
async function financeExecuteMoveAccountOperations(accountId,deleteSource=false){const source=financeAccounts().find(x=>String(x.id)===String(accountId)),targetId=String(document.getElementById('financeMoveAccountTarget')?.value||''),target=financeAccounts().find(x=>String(x.id)===targetId);if(!source)return alert('Исходный счёт не найден.');if(!target)return alert('Выберите счёт, на который перенести операции.');if(String(source.id)===String(target.id))return alert('Выберите другой счёт.');if(String(source.currency||'KZT')!==String(target.currency||'KZT'))return alert('Перенос между разными валютами недоступен.');const usage=financeTransactions().filter(x=>String(x.accountId)===String(source.id)||String(x.toAccountId)===String(source.id)).length;if(!usage)return alert('На исходном счёте уже нет операций.');if(deleteSource&&Math.abs(Number(source.balance)||0)>.000001)return alert('Перед удалением сначала переведи остаток со счёта. Его текущий баланс: '+financeMoney(Number(source.balance)||0,source.currency||'KZT'));const question='Перенести '+usage+' операций\n\n«'+source.name+'» → «'+target.name+'»?'+(deleteSource?'\n\nПосле переноса исходный счёт будет удалён.':'');if(!confirm(question))return;try{const result=await financeRunLocalMutation(()=>{let moved=0,removedInternal=0;const list=financeTransactions();for(let i=list.length-1;i>=0;i--){const tx=list[i];if(String(tx.accountId)!==String(source.id)&&String(tx.toAccountId)!==String(source.id))continue;const next={...tx};if(String(next.accountId)===String(source.id)){next.accountId=target.id;next.accountName=target.name}if(String(next.toAccountId)===String(source.id)){next.toAccountId=target.id;next.toAccountName=target.name}if(financeTransactionType(next)==='transfer'&&String(next.accountId)===String(next.toAccountId)){list.splice(i,1);removedInternal++;continue}next.updatedAt=Date.now();next.balanceDetached=true;next.balanceDetachedAt=next.updatedAt;next.affectsBalance=false;list[i]=next;moved++}if(deleteSource){const i=financeAccounts().findIndex(x=>String(x.id)===String(source.id));if(i>=0)financeAccounts().splice(i,1)}return {moved,removedInternal}},()=>[financeCommand('/api/finance/accounts/'+encodeURIComponent(source.id)+'/move-operations',{method:'POST',body:{targetId:target.id,deleteSource},acceptStatuses:deleteSource?[404]:[]})]);closeModal();alert('Перенесено операций: '+result.moved+(result.removedInternal?' · удалено внутренних переводов: '+result.removedInternal:'')+(deleteSource?' · исходный счёт удалён':''))}catch(e){alert('Не удалось перенести операции локально: '+String(e.message||e))}}
function financeCategoryLegacyIsOwnedBy(category){if(!category)return false;const normalized=financeNormalizeCategoryName(category.name),matches=financeVisibleCategories().filter(c=>financeNormalizeCategoryName(c.name)===normalized);return matches.length===1&&String(matches[0].id)===String(category.id)}
function financeCategoryTransactionBelongs(tx,category){if(!tx||!category)return false;if(String(tx.categoryId||'')===String(category.id))return true;if(String(tx.categoryId||''))return false;return financeCategoryLegacyIsOwnedBy(category)&&financeNormalizeCategoryName(tx.category)===financeNormalizeCategoryName(category.name)}
function financeCategoryUsage(category){return financeTransactions().filter(tx=>financeCategoryTransactionBelongs(tx,category)).length}
function financeMoveCategoryOperations(categoryId){const source=financeCategories().find(x=>String(x.id)===String(categoryId));if(!source)return alert('Категория не найдена.');const targets=financeVisibleCategories().filter(x=>String(x.id)!==String(source.id)).sort((a,b)=>{const sameA=financeNormalizeCategoryName(a.name)===financeNormalizeCategoryName(source.name)?0:1,sameB=financeNormalizeCategoryName(b.name)===financeNormalizeCategoryName(source.name)?0:1;return sameA-sameB||String(a.name).localeCompare(String(b.name),'ru')});if(!targets.length)return alert('Нет другой категории, куда можно перенести операции. Сначала создай категорию, которую нужно оставить.');const used=financeCategoryUsage(source);showSheet('<h3>Объединить категории</h3><div class="link-note"><b>'+esc(source.name)+'</b> · операций: '+used+'<br>Все операции будут перепривязаны к выбранной категории. После успешного переноса категория «'+esc(source.name)+'» будет полностью удалена.</div><div class="field"><label>В какую категорию перенести</label><select id="financeMoveCategoryTarget"><option value="">Выберите категорию</option>'+targets.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.name)+' · '+esc(x.kind==='expense'?'Расходы':x.kind==='income'?'Доходы':'Доходы и расходы')+'</option>').join('')+'</select></div><div class="actions"><button class="btn" onclick="closeModal()">Отмена</button><button class="btn dark" onclick="financeExecuteMoveCategoryOperations(\''+esc(source.id)+'\')">Перенести и удалить</button></div>')}
